    if numeric_aliases:
        context["required_metrics"].append("conversions")
    optional = {
        "breakdowns": {
            "facebook": {"age": [{"label": "25–34", "value": 45}]},
            "instagram": {"age": [{"label": "25–34", "value": 40}]},
